window.ATELIER = {"realiteSociale":"romanisation","titre":"Romanisation","niveau":1,"ponderation":{"Situer dans le temps":1,"Situer dans l'espace":1,"Établir des faits":1,"Dégager des différences et des similitudes":2,"Mettre en relation des faits":2,"Déterminer des changements et des continuités":2,"Déterminer des causes et des conséquences":3,"Établir des liens de causalité":3},"instruments":[{"id":"espace","op":"Situer dans l'espace","mecanique":"carte","nom":"La carte","sous":"Situer dans l'espace","latin":"SPATIVM","auto":true},{"id":"temps","op":"Situer dans le temps","mecanique":"frise","nom":"La frise","sous":"Situer dans le temps","latin":"TEMPVS","auto":true},{"id":"relation","op":"Mettre en relation des faits","mecanique":"grille","nom":"La grille","sous":"Mettre en relation des faits","latin":"NEXVS","auto":true},{"id":"faits","op":"Établir des faits","mecanique":"qcm","nom":"Le relevé de faits","sous":"Établir des faits","latin":"FACTA","auto":true},{"id":"causescq","op":"Déterminer des causes et des conséquences","mecanique":"qcm","nom":"Causes & effets","sous":"Déterminer causes et conséquences","latin":"CAVSAE","auto":true},{"id":"diff","op":"Dégager des différences et des similitudes","mecanique":"comparateur","nom":"Le comparateur","sous":"Différences et similitudes","latin":"COMPARO","auto":false},{"id":"chang","op":"Déterminer des changements et des continuités","mecanique":"tri","nom":"Le trieur","sous":"Changements et continuités","latin":"MVTATIO","auto":false},{"id":"causalite","op":"Établir des liens de causalité","mecanique":"chaine","nom":"La chaîne causale","sous":"Établir des liens de causalité","latin":"CATENA","auto":false}],"questions":[{"id":"q-rom-causalite-1","operation":"Établir des liens de causalité","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide des documents 1 à 3, explique comment l'annexion de nouveaux territoires par Rome transforme la culture des populations conquises.","bullets":["Un motif de l'annexion de nouveaux territoires","Une nouvelle province romaine au 1er siècle avant notre ère","Un impact sur la culture des populations annexées"],"instructions":[{"text":"Fais des phrases complètes et utilise des marqueurs de relation de ","bold":false},{"text":"but","bold":true},{"text":", de ","bold":false},{"text":"cause","bold":true},{"text":", de ","bold":false},{"text":"conséquence","bold":true},{"text":" ou d'","bold":false},{"text":"explication","bold":true},{"text":" afin d'établir les liens entre les éléments.","bold":false}],"responseSpace":[{"type":"lines","count":8}]},"documents":[{"id":"rom-c1-d1","title":"Document 1 : Jules César et la conquête de la Gaule","layout":"text-only","text":"Entre 58 et 51 avant notre ère, Jules César, alors consul, entreprit la conquête du nord de la Gaule avec ses 11 légions (6000 hommes par légion) : ce fut la célèbre « guerre des Gaules ». César réorganisa ensuite l'ensemble de la Gaule transalpine qu'il divisa en quatre provinces : la Narbonnaise (ex-Provincia), l'Aquitaine (Gallia Aquitania), la Lyonnaise (Gallia Lugdunensis) et la Belgique (Gallia Belgica), la Gaule entière étant conquise en 51 avant notre ère. Rome nommait des gouverneurs qui ignoraient tout de la langue gauloise pour chacune des provinces ; ils étaient chargés, entre autres, de lever les impôts que devaient payer les Gaulois et, en même temps, ils veillaient à l'entretien des voies romaines.","sources":["Source du texte : Auteur inconnu, L'expansionnisme linguistique du monde romain, en ligne, consulté le 15 décembre 2023."]},{"id":"rom-c1-d2","title":"Document 2 : Toujours plus de conquêtes","layout":"text-only","text":"Rome a pour objectif d'intégrer les territoires conquis dans son système politique et administratif afin d'étendre son influence et son contrôle sur un territoire plus vaste. L'annexion des territoires conquis répond à plusieurs besoins de la république : pacifier les relations entre Rome et les populations des territoires conquis ; romaniser les territoires en intégrant les institutions, les lois et la culture de Rome ; accéder aux ressources naturelles (blé, métaux, etc.) ; développer le système des voies romaines et les routes commerciales.","sources":["Source du texte : Service national du RÉCIT, domaine de l'univers social."]},{"id":"rom-c1-d3","title":"Document 3 : Diffusion de la culture","layout":"text-only","text":"La langue est l'un des principaux véhicules d'une culture. Les Romains imposent leur langue, le latin, comme moyen de communication officiel dans tout l'Empire. Ils diffusent aussi leur vision du monde grâce à leur langue et leurs institutions. Ils le font aussi à l'aide de la religion. En intégrant les dieux des provinces conquises à leur propre religion, ils permettent ainsi aux différentes cultures de s'intégrer à l'Empire. Par exemple, le dieu grec Arès est intégré au panthéon romain sous le nom de Mars. Partout sur le territoire, les Romains construisent des temples dédiés à chacune des divinités. Ce n'est que plus tard que Rome imposera le christianisme.","sources":["Source du texte : Service national du RÉCIT, domaine de l'univers social."]}],"corrige":[{"kind":"texte","valeur":"Rome souhaite augmenter son influence dans le bassin méditerranéen et pacifier ses relations avec les habitants des régions conquises. C'est pourquoi Rome annexe progressivement des provinces comme les Gaules. En raison de l'annexion des Gaules au territoire romain, les populations se romanisent par l'adoption forcée du latin et par la fréquentation et l'utilisation des infrastructures romaines."}],"points":3,"auto":false},{"id":"q-rom-causes-1","operation":"Déterminer des causes et des conséquences","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide des documents 1 et 2, détermine le document qui présente une cause de l'expansion territoriale et le document qui en présente une conséquence.","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Cause de l'expansion territoriale","Conséquence de l'expansion territoriale"]}]},"documents":[{"id":"rom-ca1-d1","title":"Document 1 : Vivre en paix","layout":"text-only","text":"Tout au long de leurs guerres d'expansion, les Romains ne se sont jamais considérés comme des agresseurs. Selon un historien, dans leur esprit, les guerres n'étaient menées que pour soumettre les ennemis qu'ils considéraient comme une menace pour l'intégrité romaine. L'homme d'État et auteur romain Cicéron pensait que la seule raison de la guerre était de permettre à Rome de vivre en paix.","sources":["Source du texte : Donald L. Wasson, Étendue de l'Empire Romain, World History Encyclopedia, consulté le 4 janvier 2024."]},{"id":"rom-ca1-d2","title":"Document 2 : La taille de l'empire","layout":"text-only","text":"La taille de l'empire finit par poser problème — il était trop grand pour être géré et devenait plus sensible aux invasions barbares. En 284 de notre ère, un nouvel empereur arriva au pouvoir. Il s'appellait Dioclétien [...]. Il divisa l'empire : il y avait un empereur à l'ouest — avec Rome comme capitale — et un autre empereur à l'est — avec sa capitale à Nicomédie (plus tard Constantinople).","sources":["Source du texte : Donald L. Wasson, Étendue de l'Empire Romain, World History Encyclopedia, consulté le 4 janvier 2024."]}],"corrige":[{"kind":"lettres","valeurs":["1","2"]}],"points":3,"auto":true},{"id":"q-rom-changements-1","operation":"Déterminer des changements et des continuités","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide des documents 1 et 2, détermine le changement territorial et politique qui se produit suite à la mort de Théodose 1er.","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":4}]},"documents":[{"id":"rom-ch1-d1","title":"Document 1 : La division de l'empire romain","layout":"text-only","text":"En 395, à la mort de l'empereur Théodose [...] l'Empire [...] fut partagé en deux. Théodose organisa le partage de l'Empire selon une stricte ligne droite : elle passait au milieu des actuels Serbie et Monténégro et au milieu de la Libye. À cette époque, cette division ne devait être qu'administrative. L'empire d'Occident gardait Rome comme capitale et l'empire d'Orient avait Constantinople. Mais l'unité de l'Empire était définitivement brisée, alors qu'il se trouvait divisé entre l'Empire romain d'Occident et l'Empire romain d'Orient.","sources":["Source du texte : Jacques Leclerc, L'empire romain. De -27 à 476, CEFAN, consulté le 4 janvier 2024."]},{"id":"rom-ch1-d2","title":"Document 2 : Le partage de l'empire","layout":"image-only","imageUrl":"assets/img/rom-changements-1/doc2.png","imageWidthCm":9,"sources":["Source de l'image : Jacques Leclerc, Le partage de l'Empire entre l'Occident et l'Orient dans L'empire romain. De -27 à 476, CEFAN, consulté le 4 janvier 2024."]}],"corrige":[{"kind":"texte","valeur":"L'Empire romain est divisé en 2 : l'Empire romain d'Occident et l'Empire romain d'Orient."}],"points":2,"auto":false},{"id":"q-rom-differences-1","operation":"Dégager des différences et des similitudes","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide des documents 1 et 2, dégage une similitude entre l'Édit de Milan de l'an 313 et le Traité sur la tolérance de Voltaire.","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":4}]},"documents":[{"id":"rom-di1-d1","title":"Document 1 : Édit de Milan","layout":"text-only","text":"« Depuis longtemps déjà, considérant qu'il ne faut pas refuser la liberté de la religion, mais qu'il faut accorder à la raison et à la volonté [de] chacun la faculté de s'occuper des choses divines, chacun selon sa préférence, nous avions invité les chrétiens à conserver la foi [...] de leur religion. »","sources":["Source du texte : Eusèbe de Césarée, Copie des constitutions impériales se rapportant aux chrétiens, Histoire Ecclésiastique X, V, 1-14."]},{"id":"rom-di1-d2","title":"Document 2 : Traité sur la tolérance","layout":"text-only","text":"« Il ne faut pas un grand art, une éloquence bien recherchée, pour prouver que [tous les] chrétiens doivent se tolérer les uns les autres. Je vais plus loin : je vous dis qu'il faut [considérer] tous les hommes comme nos frères [indépendamment de leur religion]. »","sources":["Source du texte : Voltaire, Traité sur la tolérance, Bibliothèque électronique du Québec, consulté le 4 janvier 2024."]}],"corrige":[{"kind":"texte","valeur":"L'Édit de Milan et le Traité sur la tolérance de Voltaire abordent l'idée de tolérer les croyances religieuses individuelles et divergentes."}],"points":2,"auto":false},{"id":"q-rom-espace-1","operation":"Situer dans l'espace","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Les documents 1 et 2 présentent le territoire de l'empire romain à deux époques distinctes. Indique le numéro du document qui correspond au territoire de l'empire romain au 2e siècle de notre ère.","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Numéro du document"]}]},"documents":[{"id":"rom-e1-d1","title":"Document 1","layout":"image-only","imageUrl":"assets/img/rom-espace-1/doc1.png","imageWidthCm":7,"sources":["Source de l'image : Coldeel, La République romaine à la mort de Jules César en [...], Wikimedia Commons. Licence : image du domaine public."]},{"id":"rom-e1-d2","title":"Document 2","layout":"image-only","imageUrl":"assets/img/rom-espace-1/doc2.png","imageWidthCm":7,"sources":["Source de l'image : Coldeel, L'Empire romain sous le règne d'Antonin le Pieux, Wikimedia Commons. Licence : image du domaine public."]}],"corrige":[{"kind":"lettres","valeurs":["2"]}],"points":1,"auto":true},{"id":"q-rom-faits-1","operation":"Établir des faits","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Indique un pouvoir que possède l'empereur romain.","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":2}]},"documents":[{"id":"rom-f1-d1","title":"Document 1 : L'empereur, le chef de l'empire","layout":"text-only","text":"À l'époque de l'Empire, c'est l'empereur qui devient le dépositaire du pouvoir. Il est le chef de l'armée et possède un droit de veto* sur le sénat dont il nomme les membres. Il est aussi chef de la religion. Il contrôle la frappe de la monnaie. Il est entouré d'un conseil privé et d'une administration impériale dirigée par des hauts fonctionnaires qui dépendent de lui. Dans chacune des provinces conquises, un gouverneur le représente. Il administre le territoire, assure sa défense, la justice et perçoit les impôts. *Droit de veto : droit à l'opposition d'une décision.","sources":["Source du texte : Service national du RÉCIT, domaine de l'univers social."]}],"corrige":[{"kind":"texte","valeur":"L'empereur nomme les membres du Sénat OU dirige l'armée OU frappe la monnaie OU il est le chef de la religion OU il nomme les gouverneurs OU il possède un droit de veto OU il peut donner la citoyenneté, etc."}],"points":1,"auto":false},{"id":"q-rom-relation-1","operation":"Mettre en relation des faits","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Les documents 1 à 3 présentent des bâtiments et des infrastructures romaines. Associe le document au bâtiment ou à l'infrastructure lui correspondant.","bullets":[],"instructions":[],"responseSpace":[{"type":"checkbox-table","columns":["Curie","Thermes","Cirque"],"rows":["Document 1","Document 2","Document 3"]}]},"documents":[{"id":"rom-r1-d1","title":"Document 1","layout":"text-only","text":"« Les plus célèbres complexes [...] étaient ceux des empereurs Caracalla et Dioclétien et pouvaient accueillir quelque 1500 baigneurs à la fois, comprenant une grande piscine d'eau froide faisant près de 2500 m². À titre de comparaison, une piscine de taille olympique moderne fait 1250 m² [...]. Ces complexes étaient gigantesques et exaltaient la richesse et la puissance de l'Empire. En allant s'y baigner et s'y reposer, on avait aussi l'impression de communier à cette « romanité » qui s'exprimait indifféremment en Italie, en Syrie, en Afrique du Nord ou dans la lointaine Bretagne. »","sources":["Source du texte : Pierre-Luc Brisson, Histoire de la Rome antique, Québec, 2020, page 132."]},{"id":"rom-r1-d2","title":"Document 2","layout":"image-only","imageUrl":"assets/img/rom-relation-1/doc2.png","imageWidthCm":7,"sources":["Source de l'image : Albert Kuhn (1913), Course de chars, Wikimedia Commons. Licence : image du domaine public."]},{"id":"rom-r1-d3","title":"Document 3","layout":"image-only","imageUrl":"assets/img/rom-relation-1/doc3.png","imageWidthCm":6,"sources":["Source de l'image : Longbow4u, [...] Julienne, construite sur l'initiative de Jules César, visible actuellement dans le forum romain (2005), Wikimedia Commons. Licence : Creative Commons (BY-SA 3.0)."]}],"corrige":[{"kind":"cases","lignes":[{"cochees":[{"coche":false},{"coche":true},{"coche":false}]},{"cochees":[{"coche":false},{"coche":false},{"coche":true}]},{"cochees":[{"coche":true},{"coche":false},{"coche":false}]}]}],"points":2,"auto":true},{"id":"q-rom-temps-1","operation":"Situer dans le temps","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Durant l'histoire de Rome, plusieurs régimes politiques se sont succédé. À l'aide du document 1, indique la lettre qui correspond à la période de l'empire romain.","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Lettre correspondante"]}]},"documents":[{"id":"rom-t1-d1","title":"Document 1 : Les régimes politiques à Rome","layout":"image-only","imageUrl":"assets/img/rom-temps-1/doc1.png","imageWidthCm":13,"sources":["Source de l'image : Mathieu Mercier."]}],"corrige":[{"kind":"lettres","valeurs":["C"]}],"points":1,"auto":true},{"id":"q-rom-causalite-2","operation":"Établir des liens de causalité","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide des documents 1 à 3, explique comment la situation territoriale de l'empire romain a participé à sa chute.","bullets":["La situation territoriale de l'empire romain au 2e siècle de notre ère","Une problématique liée à la situation territoriale","Une action des peuples germaniques"],"instructions":[{"text":"Fais des phrases complètes et utilise des marqueurs de relation de ","bold":false},{"text":"but","bold":true},{"text":", de ","bold":false},{"text":"cause","bold":true},{"text":", de ","bold":false},{"text":"conséquence","bold":true},{"text":" ou d'","bold":false},{"text":"explication","bold":true},{"text":" afin d'établir les liens entre les éléments.","bold":false}],"responseSpace":[{"type":"lines","count":8}]},"documents":[{"id":"rom-c2-d1","title":"Document 1 : Défendre l'empire ? Pas si facile !","layout":"text-only","text":"L'Empire romain couvre une vaste région, s'étendant de l'Atlantique à l'Euphrate et de la Bretagne à l'Afrique du Nord. Défendre des frontières aussi longues et variées géographiquement est complexe et coûteux. De plus, les légions qui défendent les frontières sont souvent composées de soldats locaux, ce qui entraîne des problèmes de loyauté : les soldats se sentent souvent plus attachés à leur région d'origine qu'à Rome.","sources":["Source du texte : Service national du RÉCIT, domaine de l'univers social."]},{"id":"rom-c2-d2","title":"Document 2 : Genséric pille Rome en 455","layout":"text-image","text":"Les Vandales s'emparèrent de tout ce qui avait de la valeur, qu'il s'agisse de trésors personnels, d'ornements de bâtiments ou de statues, mais ils ne détruisirent pas la ville et peu de personnes furent blessées, à l'exception de [l'empereur] qui fut tué par une foule romaine alors qu'il tentait de s'enfuir [...]. Les Vandales pillèrent la ville, puis rejoignirent leurs navires et rentrèrent chez eux, emmenant avec eux un certain nombre d'otages de premier plan [...].","imageUrl":"assets/img/rom-causalite-2/doc2.png","imageWidthCm":6,"sources":["Source du texte : Joshua J. Mark, Genséric, World History Encyclopedia, consulté le 2 janvier 2024.","Source de l'image : Karl Briullov, Le sac de Rome par Genséric en 455, Wikimedia Commons. Licence : image du domaine public."]},{"id":"rom-c2-d3","title":"Document 3 : L'empire romain à son apogée","layout":"image-only","imageUrl":"assets/img/rom-causalite-2/doc3.png","imageWidthCm":12,"sources":["Source de l'image : George Langlois et Gilles Villemure, Empire romain - expansion territoriale, Centre collégial de développement de matériel didactique. Licence : utilisation permise dans un contexte éducatif et non commercial."]}],"corrige":[{"kind":"texte","valeur":"Au 2e siècle, le territoire de l'Empire romain atteint son apogée. Un territoire aussi vaste que celui de l'empire romain au 2e siècle est difficile à protéger, surtout si on considère que les soldats frontaliers ne sont pas tous fidèles à Rome. C'est pourquoi plusieurs vagues de Germains (peuples germaniques) envahissent progressivement l'Empire romain."}],"points":3,"auto":false},{"id":"q-rom-causes-2","operation":"Déterminer des causes et des conséquences","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide du document 1, pourquoi le mur d'Hadrien a-t-il été construit au 2e siècle de notre ère ?","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":4}]},"documents":[{"id":"rom-ca1-d3","title":"Document 1 : Le limes romain","layout":"text-image","text":"« Long d'environ 120 km, le mur d'Hadrien est le monument historique le plus étendu d'Europe du Nord. Le visiteur pourrait n'y voir qu'un autre de ces nombreux murs de pierres s'élevant au milieu de vallées pleines de moutons. Mais on mesure assez vite l'importance de ce vestige archéologique, classé par l'UNESCO au patrimoine mondial de l'humanité. Et pour cause : construite entre l'an 122 et l'an 126 de notre ère par l'empereur Hadrien, cette fortification militaire, qui servait de rempart contre les Pictes venus d'Écosse, a été, pendant 300 ans, la frontière la plus au nord de l'Empire romain, qui s'étendait alors jusqu'à l'Égypte. On ose à peine imaginer comment ont réagi les barbares devant cette imposante merveille d'ingénierie. Mais elle devait être efficace, vu sa longévité. »","imageUrl":"assets/img/rom-causes-1/doc3.png","imageWidthCm":5,"sources":["Source du texte : Jean-Christophe Laurence, Le mur d'Hadrien : ici s'arrêtait l'Empire romain, La Presse, consulté le 4 janvier 2024.","Source de l'image : Talifero, Localisation du mur d'Hadrien et du mur d'Antonin en Grande-Bretagne, Wikimedia Commons. Licence : Creative Commons BY-SA 3.0."]}],"corrige":[{"kind":"texte","valeur":"Le mur d'Hadrien a été construit afin de protéger l'empire romain des peuples comme les Pictes. C'est aussi la frontière la plus au nord de l'empire romain."}],"points":3,"auto":false},{"id":"q-rom-changements-2","operation":"Déterminer des changements et des continuités","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide du document 1, détermine un changement politique qui survient en 27 avant notre ère.","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":3}]},"documents":[{"id":"rom-ch1-d3","title":"Document 1 : 1er empereur romain","layout":"image-only","imageUrl":"assets/img/rom-changements-1/doc3.png","imageWidthCm":5,"sources":["Source de l'image : General Libraries, The University of Texas at Austin, Portrait de l'empereur Auguste, Wikimedia Commons. Licence : image du domaine public."]}],"corrige":[{"kind":"texte","valeur":"La République romaine est remplacée par l'Empire."}],"points":2,"auto":false},{"id":"q-rom-differences-2","operation":"Dégager des différences et des similitudes","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide des documents 1 et 2, dégage une différence et une similitude entre l'éducation des garçons et des filles chez les enfants de patriciens.","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Différence","Similitude"]}]},"documents":[{"id":"rom-di1-d3","title":"Document 1 : L'éducation","layout":"text-only","text":"« Au sein des familles les plus aisées, les jeunes enfants étaient le plus souvent confiés à une nourrice dans la prime jeunesse, alors qu'un esclave lettré leur enseignait par la suite les rudiments de la lecture et de l'écriture. [...]. La première instruction formelle, qui va de 7 à 11 ans, était en principe dispensée aux garçons comme aux filles dans une école (ludus) sur le Forum par le magister ludi. »","sources":["Source du texte : Pierre-Luc Brisson, Histoire de la Rome antique, Québec, 2020, pages 58-59."]},{"id":"rom-di1-d4","title":"Document 2 : Objectifs distincts","layout":"text-only","text":"« L'instruction [des garçons], à partir de 16 ans, était quant à elle essentiellement oratoire et transmise par un rhéteur qui préparait le jeune citoyen à assumer, par la parole, son rôle futur sur la scène politique de la cité, que ce soit en tant qu'avocat ou que magistrat. La rhétorique était une science du discours, qui recouvrait autant l'art de la démonstration que celui de la prestation oratoire ou de la « livraison ». » « Sous la République, la jeune fille romaine n'était la plupart du temps qu'un rouage dans les stratégies matrimoniales de sa famille. Elle était fiancée vers l'âge de 6 ou 7 ans et servait à nouer des alliances politiques avec d'autres clans. Elle était mariée vers l'âge de 13 ans. Ce n'est que graduellement, sous l'Empire, que le statut de la femme romaine s'émancipa peu à peu. »","sources":["Source du texte : Pierre-Luc Brisson, Histoire de la Rome antique, Québec, 2020, pages 58-59."]}],"corrige":[{"kind":"lettres","valeurs":["Les garçons sont élevés afin de participer à la vie politique romaine, alors que les jeunes filles sont éduquées afin de devenir de bonnes épouses romaines.","Les garçons et les filles reçoivent la même éducation jusqu'à l'âge de 7 ans, auprès de leur mère."]}],"points":2,"auto":true},{"id":"q-rom-espace-2","operation":"Situer dans l'espace","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide des documents 1 à 4, situe les provinces romaines de la Bretagne (Britannia), de la Gaule aquitaine (Gallia Aquitania), de l'Afrique proconsulaire (Africa) et de l'Égypte (Ægyptus).","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Bretagne (Britannia)","Gaule Aquitaine (Gallia Aquitania)","Afrique proconsulaire (Africa)","Égypte (Ægyptus)"]}]},"documents":[{"id":"rom-e1-d3","title":"Document 1","layout":"image-only","imageUrl":"assets/img/rom-espace-1/doc3.png","imageWidthCm":7,"sources":["Source de l'image : Milenioscuro, Locator map of [...], Wikimedia Commons. Licence : Creative Commons BY-SA 4.0."]},{"id":"rom-e1-d4","title":"Document 2","layout":"image-only","imageUrl":"assets/img/rom-espace-1/doc4.png","imageWidthCm":7,"sources":["Source de l'image : Milenioscuro, Locator map of [...], Wikimedia Commons. Licence : Creative Commons BY-SA 4.0."]},{"id":"rom-e1-d5","title":"Document 3","layout":"image-only","imageUrl":"assets/img/rom-espace-1/doc5.png","imageWidthCm":7,"sources":["Source de l'image : Michiel1972, [...], Wikimedia Commons. Licence : Creative Commons BY-SA 3.0."]},{"id":"rom-e1-d6","title":"Document 4","layout":"image-only","imageUrl":"assets/img/rom-espace-1/doc6.png","imageWidthCm":7,"sources":["Source de l'image : Michiel1972, [...], Wikimedia Commons. Licence : Creative Commons BY-SA 3.0."]}],"corrige":[{"kind":"lettres","valeurs":["3","4","1","2"]}],"points":1,"auto":true},{"id":"q-rom-faits-2","operation":"Établir des faits","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Quelle infrastructure permet l'approvisionnement en eau potable des villes romaines ?","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":2}]},"documents":[{"id":"rom-f1-d2","title":"Document 1 : Approvisionnement en eau","layout":"image-only","imageUrl":"assets/img/rom-faits-1/doc2.png","imageWidthCm":13,"sources":["Source de l'image : Service national du RÉCIT, domaine de l'univers social."]}],"corrige":[{"kind":"texte","valeur":"L'aqueduc permet l'approvisionnement des villes en eau potable."}],"points":1,"auto":false},{"id":"q-rom-relation-2","operation":"Mettre en relation des faits","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide des documents 1 à 3, associe le groupe social au document qui lui correspond.","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Les patriciens","Les plébéiens","Les esclaves"]}]},"documents":[{"id":"rom-r1-d4","title":"Document 1","layout":"text-only","text":"« [...] ceux dont la famille prétendait descendre des premiers fondateurs de la cité et qui siégeaient au Sénat [...] ».","sources":["Source du texte : Pierre-Luc Brisson, Histoire de la Rome antique, Québec, 2020, page 41."]},{"id":"rom-r1-d5","title":"Document 2","layout":"text-only","text":"« [...] plus il remportait de combats, plus sa valeur marchande augmentait et plus le prestige de son ludus s'en ressentait. [...] qui remportait de nombreuses victoires et qui acquérait, par le fait même, un renom pouvait accumuler un pécule [...]. »","sources":["Source du texte : Pierre-Luc Brisson, Histoire de la Rome antique, Québec, 2020, page 101."]},{"id":"rom-r1-d6","title":"Document 3","layout":"text-only","text":"« [...] le reste du peuple, riche ou pauvre, d'origine latine ou non, et qui avait graduellement intégré la population romaine [...] ».","sources":["Source du texte : Pierre-Luc Brisson, Histoire de la Rome antique, Québec, 2020, page 41."]}],"corrige":[{"kind":"lettres","valeurs":["1","3","2"]}],"points":2,"auto":true},{"id":"q-rom-temps-2","operation":"Situer dans le temps","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Indique si les faits présentés dans les documents 1 et 2 sont antérieurs (avant) ou postérieurs (après) la Pax Romana, une importante période de paix.","bullets":[],"instructions":[],"responseSpace":[{"type":"before-after-axis","beforeLabel":"Antériorité (Avant)","afterLabel":"Postériorité (Après)","pivot":"Pax Romana (-27 à 180)"}]},"documents":[{"id":"rom-t1-d2","title":"Document 1 : Genséric pille Rome","layout":"text-image","text":"Les Vandales s'emparèrent de tout ce qui avait de la valeur, qu'il s'agisse de trésors personnels, d'ornements de bâtiments ou de statues, mais ils ne détruisirent pas la ville et peu de personnes furent blessées, à l'exception de [l'empereur] qui fut tué par une foule romaine alors qu'il tentait de s'enfuir [...]. Les Vandales pillèrent la ville, puis rejoignirent leurs navires et rentrèrent chez eux, emmenant avec eux un certain nombre d'otages de premier plan [...].","imageUrl":"assets/img/rom-temps-1/doc2.png","imageWidthCm":6,"sources":["Source du texte : Joshua J. Mark, Genséric, World History Encyclopedia, consulté le 2 janvier 2024.","Source de l'image : Karl Briullov, Le sac de Rome par Genséric en [...], Wikimedia Commons. Licence : image du domaine public."]},{"id":"rom-t1-d3","title":"Document 2 : 1er empereur romain","layout":"image-only","imageUrl":"assets/img/rom-temps-1/doc3.png","imageWidthCm":5,"sources":["Source de l'image : General Libraries, The University of Texas at Austin, Portrait de l'empereur Auguste, Wikimedia Commons. Licence : image du domaine public."]}],"corrige":[{"kind":"avant_apres","avant":["Document 2"],"apres":["Document 1"]}],"points":1,"auto":true},{"id":"q-rom-causalite-3","operation":"Établir des liens de causalité","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide des documents 1 à 3, explique comment certaines classes sociales peuvent obtenir les mêmes droits que les patriciens romains.","bullets":["Une classe sociale qui ne possède pas de droits sur le plan politique","Une manière d'obtenir la citoyenneté romaine","Un droit acquis par le nouveau citoyen romain"],"instructions":[{"text":"Fais des phrases complètes et utilise des marqueurs de relation de ","bold":false},{"text":"but","bold":true},{"text":", de ","bold":false},{"text":"cause","bold":true},{"text":", de ","bold":false},{"text":"conséquence","bold":true},{"text":" ou d'","bold":false},{"text":"explication","bold":true},{"text":" afin d'établir les liens entre les éléments.","bold":false}],"responseSpace":[{"type":"lines","count":8}]},"documents":[{"id":"rom-c3-d1","title":"Document 1 : Devenir citoyen","layout":"text-image","text":"Au début de l'empire, il faut être le fils d'un plébéien pour être considéré comme un citoyen et avoir des droits politiques. Puis, l'obtention de la citoyenneté est possible, à condition qu'on réponde à l'un des critères suivants : faire une demande à l'empereur, en présentant un dossier démontrant sa fidélité à Rome et le fait d'avoir adopté la culture romaine ; avoir servi dans l'armée durant 25 ans ; faire partie d'une cité ayant combattu pour Rome et dont tous les habitants ont obtenu la citoyenneté romaine.","imageUrl":"assets/img/rom-causalite-3/doc1.png","imageWidthCm":3.5,"sources":["Source du texte : Service national du RÉCIT, domaine de l'univers social.","Source de l'image : Pbrks, Toga Illustration-2 (2008), Wikimedia Commons. Licence : image du domaine public."]},{"id":"rom-c3-d2","title":"Document 2 : La citoyenneté romaine","layout":"text-only","text":"« [En obtenant la citoyenneté romaine], il acquiert la possibilité de transmettre à ses héritiers les attributs conférés par son rang. Il peut, sous forme de testament, s'assurer du respect de ses biens légués. Il accède également à la propriété, au port public de la toge romaine et à la déclinaison de son identité en trois noms. Le nouveau citoyen bénéficie, face à la justice romaine, de nouvelles protections telles que le bannissement des châtiments corporels ou la permission de faire appel au peuple en cas d'un jugement non mérité. »","sources":["Source du texte : Auteur inconnu, Édit de Caracalla : de quoi s'agit-il?, Futura Sciences, consulté le 2 janvier 2024."]},{"id":"rom-c3-d3","title":"Document 3 : Étranger","layout":"text-only","text":"« Le mot [pérégrin] désigne celui qui n'appartient pas à la collectivité [...]. Ce terme désigne les non-citoyens libres. Descendants d'étrangers qu'elle a vaincus, Rome a fixé leur statut. [Ils possèdent] une certaine autonomie dans la gestion de leurs affaires. »","sources":["Source du texte : Yves Perrin, L'étranger à Rome au Haut-Empire, ou des vertus et des limites d'un questionnement anachronique, 2009, p. 29-30. Dans González-Bernaldo, P., Martini, M., & Pelus-Kaplan, M. (Eds.), Étrangers et sociétés : Représentations, coexistences, interactions dans la longue durée. Presses universitaires de Rennes, 2009, 482 pages."]}],"corrige":[{"kind":"texte","valeur":"Le pérégrin ne possède pas de droits politiques. Cependant, il peut obtenir des droits politiques en devenant citoyen, grâce à une demande à l'empereur ou en servant 25 ans dans l'armée. En obtenant la citoyenneté, il obtient des droits comme celui de faire son testament, d'être propriétaire, de se marier et de participer à la vie politique."}],"points":3,"auto":false},{"id":"q-rom-causes-3","operation":"Déterminer des causes et des conséquences","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Pourquoi les Romains imposent-ils leur culture aux peuples vaincus ?","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":3}]},"documents":[{"id":"rom-ca2-d1","title":"Document 1 : Diffusion de la culture","layout":"text-image","text":"La langue est l'un des principaux véhicules d'une culture. Les Romains imposent leur langue, le latin, comme moyen de communication officiel dans tout l'Empire. Ils diffusent aussi leur vision du monde grâce à leur langue et leurs institutions. Ils le font aussi à l'aide de la religion. En intégrant les dieux des provinces conquises à leur propre religion, ils permettent ainsi aux différentes cultures de s'intégrer à l'Empire. Par exemple, le dieu grec Arès est intégré au panthéon romain sous le nom de Mars.","imageUrl":"assets/img/rom-causes-2/doc1.png","imageWidthCm":6,"sources":["Source du texte : Service national du RÉCIT, domaine de l'univers social.","Source de l'image : Brodigny, Arènes de Lutèce (vue actuelle), Wikimedia Commons. Licence : Creative Commons BY-SA 3.0."]}],"corrige":[{"kind":"texte","valeur":"Les Romains imposent leur culture aux peuples vaincus afin de favoriser leur intégration dans l'empire."}],"points":3,"auto":false},{"id":"q-rom-changements-3","operation":"Déterminer des changements et des continuités","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide des documents 1 et 2, détermine un changement dans le système de justice romain.","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":4}]},"documents":[{"id":"rom-ch2-d1","title":"Document 1 : L'Édit perpétuel","layout":"text-only","text":"Vers 131, l'empereur exige la création d'un recueil de lois, regroupant les décisions judiciaires émises par les magistrats romains. Ce code, connu sous le nom d'Édit perpétuel, est devenu le point de référence obligatoire pour tous les magistrats et gouverneurs dans l'exercice de la justice. Ce faisant, il a permis d'appliquer un ensemble de lois cohérent et uniforme dans l'ensemble de l'Empire. [Cependant], de nombreuses lois contenues dans les anciens ouvrages étaient répétitives, contradictoires ou ne répondaient tout simplement pas aux exigences d'une société qui avait évolué depuis l'époque romaine. [Avec ses] 2 000 livres et 3 millions de lignes de texte juridique, [le système de justice romain était devenu inefficace, incohérent et très mal interprété].","sources":["Source du texte : Mathieu Mercier et Mark Cartwright, Corpus Juris Civilis, World History Encyclopedia, consulté le 4 janvier 2024."]},{"id":"rom-ch2-d2","title":"Document 2 : Le Code Justinien","layout":"text-only","text":"[Avec le Code Justinien], l'empereur atteint ses multiples objectifs : rendre les lois plus claires pour tous, réduire le nombre d'affaires portées devant les tribunaux (beaucoup étaient fondées sur des malentendus et une mauvaise interprétation de ce qu'était réellement la loi) et accélérer le traitement des affaires juridiques.","sources":["Source du texte : Mark Cartwright, Corpus Juris Civilis, World History Encyclopedia, consulté le 4 janvier 2024."]}],"corrige":[{"kind":"texte","valeur":"Le Code Justinien remplace l'Édit perpétuel afin de simplifier le droit romain et d'accélérer les décisions juridiques."}],"points":2,"auto":false},{"id":"q-rom-differences-3","operation":"Dégager des différences et des similitudes","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide des documents 1 et 2, dégage une différence entre les fonctions d'un sénateur et celles de l'empereur romain.","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":5}]},"documents":[{"id":"rom-di2-d1","title":"Document 1 : Le Sénat","layout":"text-only","text":"Le Sénat resta une institution influente même après qu'Auguste fut devenu empereur. Les sénateurs continuaient à débattre et parfois à désapprouver les actions de l'empereur, et comme le remarque l'historien F. Santangelo, le Sénat « conservait des prérogatives importantes dans les domaines militaires, fiscaux et religieux, et nommait les gouverneurs des provinces qui n'étaient pas sous le contrôle direct d'Auguste ». Certaines affaires juridiques impliquant des sénateurs ou non (par exemple la corruption, l'extorsion et les crimes contre le peuple) étaient tranchées par le Sénat et leur décision ne pouvait pas être annulée par l'empereur.","sources":["Source du texte : Mark Cartwright, Sénat romain, World History Encyclopedia, consulté le 4 janvier 2024."]},{"id":"rom-di2-d2","title":"Document 2 : L'empereur, le chef de l'Empire","layout":"text-only","text":"À l'époque de l'Empire, c'est l'empereur qui devient le dépositaire du pouvoir. Il est le chef de l'armée et possède un droit de veto* sur le sénat dont il nomme les membres. Il est aussi chef de la religion. Il contrôle la frappe de la monnaie. Il est entouré d'un conseil privé et d'une administration impériale dirigée par des hauts fonctionnaires qui dépendent de lui. Dans chacune des provinces conquises, un gouverneur le représente. Il administre le territoire, assure sa défense, la justice et perçoit les impôts. *Droit de veto : droit à l'opposition d'une décision.","sources":["Source du texte : Service national du RÉCIT de l'univers social."]}],"corrige":[{"kind":"texte","valeur":"Le sénateur possède certaines fonctions dans les domaines militaire, fiscal et religieux, alors que l'empereur possède le pouvoir de nommer les sénateurs, de frapper la monnaie et il est le chef de l'armée. En somme, l'empereur dirige, les sénateurs administrent."}],"points":2,"auto":false},{"id":"q-rom-espace-3","operation":"Situer dans l'espace","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide du document 1, indique la lettre qui correspond à la ville de Rome.","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Rome"]}]},"documents":[{"id":"rom-e2-d1","title":"Document 1 : Les villes romaines","layout":"image-only","imageUrl":"assets/img/rom-espace-2/doc1.png","imageWidthCm":13,"sources":["Source de l'image : Walter Scheidel et Elijah Meeks, Orbis The Stanford Geospatial Network Model of the Roman World, en ligne, consulté le 3 janvier 2024."]}],"corrige":[{"kind":"lettres","valeurs":["C"]}],"points":1,"auto":true},{"id":"q-rom-faits-3","operation":"Établir des faits","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Indique une fonction des provinces romaines.","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":2}]},"documents":[{"id":"rom-f2-d1","title":"Document 1 : Un empire commercial","layout":"text-only","text":"« À chaque saison de l'année, surtout à l'automne, tant de navires de transport viennent aborder [le] quai du Tibre que Rome [se transforme en un] marché universel du monde. Les cargaisons venues de l'Inde et de l'Arabie [...], on peut les voir ici en grande quantité. Les tissus de Babylone et les bijoux des pays barbares* les plus lointains arrivent à Rome en grand nombre et facilement. Vos champs, ce sont l'Égypte, la Sicile, la partie cultivée de l'Afrique. On peut dire que ce que l'on n'a jamais vu ici n'existe pas ou n'a jamais existé. » *Barbare : mot qui désigne les peuples résidant à l'extérieur de l'Empire romain.","sources":["Source du texte : D'après un discours d'Aelius Aristide, Éloge de Rome (2e siècle ap. J.-C.), cité dans Denise Galloy et Franz Hayt, Le monde romain, Bruxelles, De Boek, 1995, p. 37."]}],"corrige":[{"kind":"texte","valeur":"Fournir Rome en matières premières et en produits de toutes sortes."}],"points":1,"auto":false},{"id":"q-rom-relation-3","operation":"Mettre en relation des faits","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Les documents 1 à 3 présentent des bâtiments et des infrastructures romaines. Associe le document au bâtiment ou à l'infrastructure lui correspondant.","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Aqueduc","Arc de triomphe","Théâtre"]}]},"documents":[{"id":"rom-r2-d1","title":"Document 1","layout":"image-only","imageUrl":"assets/img/rom-relation-2/doc1.png","imageWidthCm":8,"sources":["Source de l'image : Bernard Gagnon, [...] de Ségovie, Espagne, Wikimedia Commons. Licence : Creative Commons (BY-SA 3.0)."]},{"id":"rom-r2-d2","title":"Document 2","layout":"image-only","imageUrl":"assets/img/rom-relation-2/doc2.png","imageWidthCm":7,"sources":["Source de l'image : Adrian Schneider, Roman [...] in Aspendos, Wikimedia Commons. Licence : Creative Commons BY-SA 2.5."]},{"id":"rom-r2-d3","title":"Document 3","layout":"text-only","text":"« Non loin du Colisée, sur le Forum romain, [...] commémore la victoire romaine contre les Juifs révoltés, Titus y étant représenté en triomphateur, précédé du butin du Temple qui fut détruit par les troupes romaines et dont il ne subsiste aujourd'hui qu'une partie du mur de soutènement, baptisé Mur des Lamentations. »","sources":["Source du texte : Pierre-Luc Brisson, Histoire de la Rome antique, Québec, 2020, page 139."]}],"corrige":[{"kind":"lettres","valeurs":["1","3","2"]}],"points":2,"auto":true},{"id":"q-rom-temps-3","operation":"Situer dans le temps","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Les documents 1 à 3 présentent des faits relatifs à la chute de l'Empire romain. Place ces documents en ordre chronologique.","bullets":[],"instructions":[],"responseSpace":[{"type":"chrono-ordering","items":["1er (le plus ancien)","2e","3e (le plus récent)"]}]},"documents":[{"id":"rom-t2-d1","title":"Document 1 : La division de l'empire romain","layout":"text-only","text":"La division de l'empire romain débute sous l'empereur Dioclétien en 285. Il divise alors le territoire en deux entités administratives distinctes : l'empire romain d'Occident et l'empire romain d'Orient. Cette séparation est censée permettre une gestion plus efficace et une réponse plus rapide aux menaces militaires. Malgré ses intentions, cette division a contribué à l'affaiblissement de l'empire romain d'Occident et à la montée en puissance de l'empire romain d'Orient.","sources":["Source du texte : Mathieu Mercier."]},{"id":"rom-t2-d2","title":"Document 2","layout":"image-only","imageUrl":"assets/img/rom-temps-2/doc2.png","imageWidthCm":8,"sources":["Source de l'image : Charlotte Mary Yonge, Romulus Augustulus dépose les ornements impériaux aux pieds d'Odoacre. Illustration d'un manuel d'histoire de 1880, Wikimedia Commons. Licence : image du domaine public."]},{"id":"rom-t2-d3","title":"Document 3 : La paix romaine","layout":"text-only","text":"« La Pax Romana (paix romaine) fut une période de paix et de stabilité relatives dans l'Empire romain qui dura plus de 200 ans, à partir du règne d'Auguste. L'objectif d'Auguste et de ses successeurs était de garantir la loi, l'ordre et la sécurité au sein de l'empire, même si cela impliquait de le séparer du reste du monde et de défendre, voire d'étendre, ses frontières par des interventions militaires et des conquêtes. »","sources":["Source du texte : Donald L. Wasson, Pax Romana, World History Encyclopedia, consulté le 3 janvier 2024."]}],"corrige":[{"kind":"lettres","valeurs":["Document 3","Document 1","Document 2"]}],"points":1,"auto":true},{"id":"q-rom-causes-4","operation":"Déterminer des causes et des conséquences","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide du document 1, détermine une cause politique et une cause économique du développement des voies romaines.","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Cause politique","Cause économique"]}]},"documents":[{"id":"rom-ca2-d2","title":"Document 1 : Tous les chemins mènent à Rome","layout":"text-image","text":"Au début, la route a une fonction [...]. Puis, peu à peu, tous ceux qui ont besoin de se rendre dans les nombreuses régions de l'Empire y circulent. Les commerçants utilisent aussi ce système routier pour le transport des marchandises. Ce réseau de communication permet la diffusion des coutumes, des lois et de la culture romaine dans les villes de tout l'Empire. Au maximum de son expansion, l'Empire romain dispose d'un réseau routier de plus de 80 000 kilomètres couvrant l'équivalent d'une trentaine de pays actuels. Ces routes ont été construites par les soldats pour se déplacer rapidement vers les territoires à conquérir ou à protéger. On y circule à pied, à dos de cheval ou de mulet, ou en charrette.","imageUrl":"assets/img/rom-causes-2/doc2.png","imageWidthCm":8,"sources":["Source du texte : Service national du RÉCIT, domaine de l'univers social.","Source de l'image : Le réseau de communication de l'Empire romain au 2e siècle ap. J.-C., RÉCIT national de l'univers social. Licence : Creative Commons (BY-NC-SA)."]}],"corrige":[{"kind":"lettres","valeurs":["Les voies romaines permettent la diffusion des lois dans l'empire romain OU permettent le déplacement des soldats afin de protéger ou de conquérir des territoires.","Les voies romaines servaient au développement du commerce et au transport des marchandises."]}],"points":3,"auto":true},{"id":"q-rom-changements-4","operation":"Déterminer des changements et des continuités","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide du document 1, détermine un changement juridique amené par l'instauration du Code Justinien.","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":3}]},"documents":[{"id":"rom-ch2-d3","title":"Document 1 : La présomption d'innocence","layout":"text-only","text":"Le Code Justinien, publié en 529, a jeté les bases de la justice moderne. En effet, on y retrouve des articles concernant les éléments suivants : Présomption d'innocence : Renforcement du principe d'innocence jusqu'à preuve de culpabilité, essentiel pour protéger contre les jugements injustes et les accusations infondées. Fardeau de la preuve : Obligation pour le plaignant de fournir des preuves pour étayer ses allégations, évitant ainsi les accusations non fondées. Jugements basés sur des preuves : Insistance sur des jugements fondés sur des preuves concrètes et vérifiables pour assurer l'équité et l'objectivité judiciaires.","sources":["Source du texte : Mathieu Mercier."]}],"corrige":[{"kind":"texte","valeur":"Le Code Justinien permet la mise en place de la présomption d'innocence dans l'Empire romain."}],"points":2,"auto":false},{"id":"q-rom-differences-4","operation":"Dégager des différences et des similitudes","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide du document 1, dégage une différence quant aux capitales des empires romains d'Occident et d'Orient.","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":3}]},"documents":[{"id":"rom-di2-d3","title":"Document 1 : Le partage de l'empire","layout":"image-only","imageUrl":"assets/img/rom-changements-1/doc2.png","imageWidthCm":9,"sources":["Source de l'image : Jacques Leclerc, Le partage de l'Empire entre l'Occident et l'Orient dans L'empire romain. De -27 à 476, CEFAN, consulté le 4 janvier 2024."]}],"corrige":[{"kind":"texte","valeur":"La capitale de l'Empire romain d'Occident est Rome, alors que la capitale de l'Empire romain d'Orient est Constantinople."}],"points":2,"auto":false},{"id":"q-rom-espace-4","operation":"Situer dans l'espace","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide du document 1, situe les mers Adriatique, Ionienne et Tyrrhénienne.","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Mer Adriatique","Mer Ionienne","Mer Tyrrhénienne"]}]},"documents":[{"id":"rom-e2-d2","title":"Document 1 : L'Italie","layout":"image-only","imageUrl":"assets/img/rom-espace-2/doc2.png","imageWidthCm":7,"sources":["Source de l'image : Adapté par Mathieu Mercier, D-Maps."]}],"corrige":[{"kind":"lettres","valeurs":["B","C","A"]}],"points":1,"auto":true},{"id":"q-rom-faits-4","operation":"Établir des faits","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Indique deux lieux où les Romains se divertissent.","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":2}]},"documents":[{"id":"rom-f2-d2","title":"Document 1 : Du pain et des jeux","layout":"text-only","text":"50 000 personnes peuvent venir assister aux combats de gladiateurs dans le Colisée de Rome alors que le Circus Maximus peut accueillir près de 350 000 amateurs de courses de chars. Ces immenses édifices publics, présents aussi dans les grandes villes des provinces romaines, ont une vocation culturelle. Les différents jeux sont organisés à des fins religieuses et politiques. L'État s'assure ainsi la faveur des dieux et surtout celle de la population.","sources":["Source du texte : Service national du RÉCIT, domaine de l'univers social."]},{"id":"rom-f2-d3","title":"Document 2","layout":"image-only","imageUrl":"assets/img/rom-faits-2/doc3.png","imageWidthCm":7,"sources":["Source de l'image : Adrian Schneider, Roman theater in Aspendos, Wikimedia Commons. Licence : Creative Commons BY-SA 2.5."]}],"corrige":[{"kind":"texte","valeur":"Le colisée (ou l'amphithéâtre), le cirque romain et le théâtre."}],"points":1,"auto":false},{"id":"q-rom-relation-4","operation":"Mettre en relation des faits","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Prends connaissance des documents 1 et 2. Ensuite, indique le numéro du document qui illustre le concept de romanisation.","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Numéro du document"]}]},"documents":[{"id":"rom-r2-d4","title":"Document 1","layout":"text-only","text":"« La première instruction formelle, qui va de 7 à 11 ans, était en principe dispensée aux garçons comme aux filles dans une école (ludus) sur le Forum par le magister ludi. Si les jeunes romaines dépassaient rarement cette première instruction [...], les jeunes garçons issus des familles les plus nanties avaient accès, de 12 à 16 ans, à l'éducation assurée par un grammairien, le grammaticus, qui les initiait au grec et à l'étude des lettres classiques. »","sources":["Source du texte : Pierre-Luc Brisson, Histoire de la Rome antique, Québec, 2020, page 58."]},{"id":"rom-r2-d5","title":"Document 2","layout":"text-only","text":"Ils le font aussi à l'aide de la religion. En intégrant les dieux des provinces conquises à leur propre religion, ils permettent ainsi aux différentes cultures de s'intégrer à l'Empire. Par exemple, le dieu grec Arès est intégré au panthéon romain sous le nom de Mars. Partout sur le territoire, les Romains construisent des temples dédiés à chacune des divinités.","sources":["Source du texte : Service national du RÉCIT, domaine de l'univers social."]}],"corrige":[{"kind":"lettres","valeurs":["2"]}],"points":2,"auto":true},{"id":"q-rom-temps-4","operation":"Situer dans le temps","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Sur la ligne du temps du document 1, encercle la lettre qui correspond au 5e siècle de notre ère. Inscris ta réponse ci-dessous.","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Lettre correspondante"]}]},"documents":[{"id":"rom-t2-d4","title":"Document 1 : Ligne du temps","layout":"image-only","imageUrl":"assets/img/rom-temps-2/timeline.png","imageWidthCm":13,"sources":["Source de l'image : Mathieu Mercier."]}],"corrige":[{"kind":"lettres","valeurs":["D"]}],"points":1,"auto":true},{"id":"q-rom-causes-5","operation":"Déterminer des causes et des conséquences","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Pourquoi l'éducation du fils d'un patricien est-elle orientée vers l'art oratoire et l'art de la rhétorique ?","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":4}]},"documents":[{"id":"rom-ca3-d1","title":"Document 1 : L'éducation des garçons","layout":"text-only","text":"« L'instruction « supérieure », à partir de 16 ans, était quant à elle essentiellement oratoire et transmise par un rhéteur qui préparait le jeune citoyen à assumer, par la parole, son rôle futur sur la scène politique de la cité, que ce soit en tant qu'avocat ou que magistrat. La rhétorique était une science du discours, qui recouvrait autant l'art de la démonstration que celui de la prestation oratoire ou de la « livraison ». Le débit de l'orateur, son ton, voire la posture de son corps et le positionnement de ses mains, de même que les effets de toges dramatiques, étaient minutieusement étudiés afin d'appuyer son discours. [...]. »","sources":["Source du texte : Pierre-Luc Brisson, Histoire de la Rome antique, Québec, 2020, pages 58-59."]}],"corrige":[{"kind":"texte","valeur":"Elle est orientée vers l'art oratoire et de la rhétorique afin que son éducation lui permette de participer à la vie politique romaine."}],"points":3,"auto":false},{"id":"q-rom-faits-5","operation":"Établir des faits","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Quelle est la fonction des jeux organisés dans l'empire romain ?","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":3}]},"documents":[{"id":"rom-f2-d2","title":"Document 1 : Du pain et des jeux","layout":"text-only","text":"50 000 personnes peuvent venir assister aux combats de gladiateurs dans le Colisée de Rome alors que le Circus Maximus peut accueillir près de 350 000 amateurs de courses de chars. Ces immenses édifices publics, présents aussi dans les grandes villes des provinces romaines, ont une vocation culturelle. Les différents jeux sont organisés à des fins religieuses et politiques. L'État s'assure ainsi la faveur des dieux et surtout celle de la population.","sources":["Source du texte : Service national du RÉCIT, domaine de l'univers social."]}],"corrige":[{"kind":"texte","valeur":"Les jeux sont organisés à des fins (pour des raisons) religieuses ou politiques. En d'autres termes, c'est pour avoir la faveur des dieux ou de la population."}],"points":1,"auto":false},{"id":"q-rom-causes-6","operation":"Déterminer des causes et des conséquences","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Pourquoi les frontières de l'empire romain sont-elles difficiles à protéger au cours du Bas-Empire (235-476) ?","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":4}]},"documents":[{"id":"rom-ca3-d2","title":"Document 1 : Défendre l'empire ? Pas si facile !","layout":"text-only","text":"L'Empire romain couvre une vaste région, s'étendant de l'Atlantique à l'Euphrate et de la Bretagne à l'Afrique du Nord. Défendre des frontières aussi longues et variées géographiquement est complexe et coûteux. De plus, les légions qui défendent les frontières sont souvent composées de soldats locaux, ce qui entraîne des problèmes de loyauté : les soldats se sentent souvent plus attachés à leur région d'origine qu'à Rome.","sources":["Source du texte : Service national du RÉCIT, domaine de l'univers social."]}],"corrige":[{"kind":"texte","valeur":"La défense coûteuse d'une immense frontière et la fidélité variable des soldats rendent les frontières difficiles à protéger."}],"points":3,"auto":false},{"id":"q-rom-faits-6","operation":"Établir des faits","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Quelle est la classe sociale décrite dans le document 1 ?","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":2}]},"documents":[{"id":"rom-f3-d1","title":"Document 1","layout":"text-only","text":"Les [...] sont des citoyens ordinaires, ne faisant pas partie de la classe aristocratique des patriciens. Ils étaient souvent des artisans, des commerçants, des fermiers ou des ouvriers, constituant la majorité de la population romaine. Les [...] habitaient généralement dans des appartements modestes ou des maisons en rangée, appelées insulae. Ils portaient des vêtements simples, typiquement une tunique en laine ou en lin. Malgré leur statut social inférieur, les [...] avaient certains droits politiques et pouvaient participer à l'Assemblée plébéienne. Au fil du temps, ils ont acquis plus de droits et d'influence, notamment grâce aux Tribuns de la Plèbe, qui représentaient leurs intérêts.","sources":["Source du texte : Mathieu Mercier."]}],"corrige":[{"kind":"texte","valeur":"Le document 1 présente la classe sociale suivante : le plébéien."}],"points":1,"auto":false},{"id":"q-rom-causes-7","operation":"Déterminer des causes et des conséquences","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"Détermine une conséquence de l'Édit de Caracalla de 212 sur les droits des pérégrins.","bullets":[],"instructions":[],"responseSpace":[{"type":"lines","count":3}]},"documents":[{"id":"rom-ca3-d3","title":"Document 1 : L'Édit de Caracalla","layout":"text-only","text":"« [En obtenant la citoyenneté romaine], il acquiert la possibilité de transmettre à ses héritiers les attributs conférés par son rang. Il peut, sous forme de testament, s'assurer du respect de ses biens légués. Il accède également à la propriété, au port public de la toge romaine et à la déclinaison de son identité en trois noms. Le nouveau citoyen bénéficie, face à la justice romaine, de nouvelles protections telles que le bannissement des châtiments corporels ou la permission de faire appel au peuple en cas d'un jugement non mérité. »","sources":["Source du texte : Auteur inconnu, Édit de Caracalla : de quoi s'agit-il?, Futura Sciences, consulté le 2 janvier 2024."]}],"corrige":[{"kind":"texte","valeur":"L'Édit de Caracalla permet à tous les pérégrins de devenir des citoyens romains."}],"points":3,"auto":false},{"id":"q-rom-faits-7","operation":"Établir des faits","niveau":1,"realite_sociale_id":"romanisation","questionBody":{"prompt":"À l'aide du document 1, indique un rôle économique et un rôle politique du gouverneur d'une province romaine.","bullets":[],"instructions":[],"responseSpace":[{"type":"labeled-list","items":["Rôle économique","Rôle politique"]}]},"documents":[{"id":"rom-f3-d2","title":"Document 1 : Gouverneur","layout":"text-image","text":"Rome nommait des gouverneurs pour chacune des provinces : ils étaient chargés, entre autres, de lever les impôts que devaient payer les Gaulois et, en même temps, ils veillaient à l'entretien des voies romaines. [De plus, ils] commandaient les légions romaines et étaient responsables de la défense de la province contre les invasions étrangères et les rébellions. Ils devaient maintenir la paix et la stabilité dans la région.","imageUrl":"assets/img/rom-faits-3/doc2.png","imageWidthCm":4,"sources":["Source du texte : Auteur inconnu, L'expansionnisme linguistique du monde romain, en ligne, consulté le 15 décembre 2023.","Source de l'image : Classical Numismatic Group, Inc., \"Ides of March\" denarius (obverse) of the conspirator Brutus, Wikimedia Commons. Licence : Creative Commons BY-SA 2.5."]}],"corrige":[{"kind":"lettres","valeurs":["Lever les impôts.","Commander les légions romaines OU Responsable de la défense OU Maintenir la paix OU Faire appliquer les lois."]}],"points":1,"auto":true}],"drag":{"chang":{"type":"tri","ancre":"q-rom-changements-1","_gabarit":true,"prompt":"Avec la romanisation d'un territoire conquis, classe chaque élément selon qu'il représente un changement apporté par Rome ou une continuité de la vie locale.","zones":[{"id":"chgt","label":"Changement"},{"id":"cont","label":"Continuité"}],"items":[{"id":"i1","texte":"Adoption du latin dans l'administration","zone":"chgt"},{"id":"i2","texte":"Construction de routes pavées et d'aqueducs","zone":"chgt"},{"id":"i3","texte":"Application du droit romain","zone":"chgt"},{"id":"i4","texte":"Maintien des langues et coutumes locales au quotidien","zone":"cont"},{"id":"i5","texte":"Culte de divinités locales préexistantes","zone":"cont"}]},"diff":{"type":"comparateur","ancre":"q-rom-differences-1","_gabarit":true,"prompt":"Compare l'Édit de Milan (313) et le Traité sur la tolérance de Voltaire : place chaque caractéristique dans la bonne zone.","zones":[{"id":"a","label":"Propre à l'Édit de Milan"},{"id":"commun","label":"Commun aux deux"},{"id":"b","label":"Propre à Voltaire"}],"items":[{"id":"d1","texte":"Tolère les croyances religieuses divergentes","zone":"commun"},{"id":"d2","texte":"Promu par un empereur romain (Constantin)","zone":"a"},{"id":"d3","texte":"Met fin à la persécution des chrétiens","zone":"a"},{"id":"d4","texte":"Écrit par un philosophe des Lumières","zone":"b"},{"id":"d5","texte":"S'inscrit dans la critique de l'intolérance au 18e siècle","zone":"b"}]},"causalite":{"type":"chaine","ancre":"q-rom-causalite-1","_gabarit":true,"prompt":"Reconstitue la chaîne causale de la romanisation des Gaules en ordonnant les maillons, du motif initial à l'impact culturel.","items":[{"id":"c1","texte":"Rome veut accroître son influence et pacifier le bassin méditerranéen"},{"id":"c2","texte":"Rome annexe progressivement de nouvelles provinces, comme les Gaules"},{"id":"c3","texte":"Les populations adoptent le latin et fréquentent les infrastructures romaines"},{"id":"c4","texte":"La culture des populations conquises se romanise"}],"ordre":["c1","c2","c3","c4"]}}};
